from sqlalchemy import String, Integer, Float, DateTime, Text, JSON, ForeignKey, Boolean
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column
from datetime import datetime, timezone
class Base(DeclarativeBase): pass
class AdminUser(Base):
    __tablename__='admin_users'; id:Mapped[int]=mapped_column(primary_key=True); username:Mapped[str]=mapped_column(String(100),unique=True); password_hash:Mapped[str]=mapped_column(String(255))
class Workspace(Base):
    __tablename__='workspaces'; id:Mapped[int]=mapped_column(primary_key=True); name:Mapped[str]=mapped_column(String(200)); slug:Mapped[str]=mapped_column(String(100),unique=True); created_at:Mapped[datetime]=mapped_column(DateTime,default=lambda:datetime.now(timezone.utc))
class Product(Base):
    __tablename__='products'; id:Mapped[int]=mapped_column(primary_key=True); workspace_id:Mapped[int]=mapped_column(ForeignKey('workspaces.id'),index=True); name:Mapped[str]=mapped_column(String(300)); brand:Mapped[str|None]=mapped_column(String(120),nullable=True); category:Mapped[str|None]=mapped_column(String(100),nullable=True); description:Mapped[str|None]=mapped_column(Text,nullable=True); source_url:Mapped[str|None]=mapped_column(String(1000),nullable=True); source_type:Mapped[str]=mapped_column(String(30),default='demo'); created_at:Mapped[datetime]=mapped_column(DateTime,default=lambda:datetime.now(timezone.utc))
class Review(Base):
    __tablename__='reviews'; id:Mapped[int]=mapped_column(primary_key=True); workspace_id:Mapped[int]=mapped_column(ForeignKey('workspaces.id'),index=True); product_id:Mapped[int]=mapped_column(ForeignKey('products.id'),index=True); external_id:Mapped[str|None]=mapped_column(String(200),nullable=True); title:Mapped[str|None]=mapped_column(String(500),nullable=True); review_text:Mapped[str]=mapped_column(Text); star_rating:Mapped[int|None]=mapped_column(Integer,nullable=True); author:Mapped[str|None]=mapped_column(String(200),nullable=True); review_date:Mapped[str|None]=mapped_column(String(40),nullable=True); source_url:Mapped[str|None]=mapped_column(String(1000),nullable=True); source_type:Mapped[str]=mapped_column(String(30),default='upload'); created_at:Mapped[datetime]=mapped_column(DateTime,default=lambda:datetime.now(timezone.utc)); status:Mapped[str]=mapped_column(String(30),default='pending'); sentiment:Mapped[str|None]=mapped_column(String(30),nullable=True); confidence:Mapped[float|None]=mapped_column(Float,nullable=True); themes:Mapped[list]=mapped_column(JSON,default=list); citations:Mapped[list]=mapped_column(JSON,default=list); analysis_version:Mapped[str|None]=mapped_column(String(100),nullable=True); trace:Mapped[dict|None]=mapped_column(JSON,nullable=True)
class AnalysisJob(Base):
    __tablename__='analysis_jobs'; id:Mapped[int]=mapped_column(primary_key=True); workspace_id:Mapped[int]=mapped_column(ForeignKey('workspaces.id'),index=True); kind:Mapped[str]=mapped_column(String(50),default='mock_analysis'); status:Mapped[str]=mapped_column(String(30),default='queued'); input_count:Mapped[int]=mapped_column(Integer,default=0); processed_count:Mapped[int]=mapped_column(Integer,default=0); version:Mapped[str]=mapped_column(String(100),default='mock-v1'); created_at:Mapped[datetime]=mapped_column(DateTime,default=lambda:datetime.now(timezone.utc)); finished_at:Mapped[datetime|None]=mapped_column(DateTime,nullable=True)
